/* pngsteg.c — PNG pixel-domain carrier for beaut.
 *
 * A package is a 64x64 RGBA PNG.  Every pixel byte carries data:
 *   - bytes [0, PNG_OFFSET) are deterministic filler,
 *   - bytes [PNG_OFFSET, ...) hold a fixed header + XChaCha20-Poly1305 blob,
 *   - the remaining bytes are deterministic filler.
 * Filler is a keyed BLAKE2b stream (cluster key, stamp, seq, block); there is
 * no random seed, so a package can be regenerated byte-for-byte.
 */
#include "pngsteg.h"
#include "crypt.h"
#include "ft.h"
#include <sodium.h>
#include <zlib.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>

typedef struct {
    char stamp[STEG_STAMP_LEN + 1];
    uint32_t seq, total;
    int eop;
    unsigned char sha[32];
    unsigned char *data;
    size_t len;
} pkg_t;

static uint32_t get32(const unsigned char *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | p[3];
}
static void put32(unsigned char *p, uint32_t v) {
    p[0] = (unsigned char)(v >> 24); p[1] = (unsigned char)(v >> 16);
    p[2] = (unsigned char)(v >> 8);  p[3] = (unsigned char)v;
}
static long long steg_max(void) {
    const char *s = getenv("STEGANO_MAX_SIZE");
    if (!s || !*s) return STEGANO_MAX_SIZE_DEFAULT;
    return strtoll(s, NULL, 10);
}
static int steg_key(unsigned char *key) {
    const char *pw = getenv("BEAUT_PASSWORD");
    if (!pw || !*pw) { fputs("steg: BEAUT_PASSWORD unset\n", stderr); return -1; }
    beaut_derive_key(key, pw, crypto_pwhash_OPSLIMIT_INTERACTIVE, crypto_pwhash_MEMLIMIT_INTERACTIVE);
    return 0;
}
static int stamp_ok(const char *s) {
    if (!s || strlen(s) != STEG_STAMP_LEN) return 0;
    for (int i = 0; i < STEG_STAMP_LEN; i++) {
        char c = s[i];
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')))
            return 0;
    }
    return 1;
}
static void make_stamp(char *out) {
    char date[9];
    time_t now = time(NULL);
    struct tm tm;
    localtime_r(&now, &tm);
    strftime(date, sizeof(date), "%Y%m%d", &tm);
    unsigned char r[4];
    randombytes_buf(r, sizeof(r));
    char hx[HEXBUF(4)];
    hex_encode(hx, r, sizeof(r));
    snprintf(out, STEG_STAMP_LEN + 1, "%s%s", date, hx);
}
static void sanitize_addr(char *out, size_t n, const char *in) {
    if (!in || !*in) in = "local";
    size_t j = 0;
    for (size_t i = 0; in[i] && j + 1 < n; i++) {
        char c = in[i];
        if ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') ||
            (c >= 'A' && c <= 'Z') || c == '.' || c == '-' || c == '_')
            out[j++] = c;
        else
            out[j++] = '_';
    }
    out[j] = 0;
}

/* ── deterministic filler ────────────────────────────────────────────────── */

static void filler(unsigned char *dst, size_t n, const unsigned char *key,
                   const char *stamp, uint32_t seq) {
    unsigned char h[32];
    for (size_t off = 0; off < n; off += sizeof(h)) {
        char msg[128];
        int m = snprintf(msg, sizeof(msg), "beaut-steg-filler|%s|%u|%zu",
                         stamp, seq, off / sizeof(h));
        crypto_generichash(h, sizeof(h), (unsigned char *)msg, (size_t)m, key, KEY_BYTES);
        size_t take = n - off < sizeof(h) ? n - off : sizeof(h);
        memcpy(dst + off, h, take);
    }
    sodium_memzero(h, sizeof(h));
}

/* ── PNG writer ──────────────────────────────────────────────────────────── */

static int write_chunk(FILE *f, const char *type, const unsigned char *data, uint32_t len) {
    unsigned char b[4];
    put32(b, len);
    if (fwrite(b, 1, 4, f) != 4) return -1;
    if (fwrite(type, 1, 4, f) != 4) return -1;
    if (len && data && fwrite(data, 1, len, f) != len) return -1;
    uLong crc = crc32(0L, Z_NULL, 0);
    crc = crc32(crc, (const Bytef *)type, 4);
    if (len) crc = crc32(crc, data, len);
    put32(b, (uint32_t)crc);
    return fwrite(b, 1, 4, f) == 4 ? 0 : -1;
}
static int write_png(const char *path, const unsigned char *px) {
    static const unsigned char sig[8] = { 0x89, 'P', 'N', 'G', '\r', '\n', 0x1a, '\n' };
    size_t stride = PNG_W * PNG_CHANNELS;
    size_t rawlen = PNG_H * (stride + 1);
    unsigned char *raw = malloc(rawlen);
    if (!raw) return -1;
    for (int y = 0; y < PNG_H; y++) {
        raw[y * (stride + 1)] = 0;   /* filter: none */
        memcpy(raw + y * (stride + 1) + 1, px + (size_t)y * stride, stride);
    }
    uLongf clen = compressBound((uLong)rawlen);
    unsigned char *comp = malloc(clen ? clen : 1);
    if (!comp || compress2(comp, &clen, raw, (uLong)rawlen, 9) != Z_OK) {
        free(raw); free(comp); return -1;
    }
    free(raw);

    unsigned char ihdr[13];
    put32(ihdr, PNG_W); put32(ihdr + 4, PNG_H);
    ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;

    char tmp[1300];
    snprintf(tmp, sizeof(tmp), "%s.tmp.%ld", path, (long)getpid());
    FILE *f = fopen(tmp, "wb");
    if (!f) { free(comp); return -1; }
    int ok = fwrite(sig, 1, 8, f) == 8 &&
             write_chunk(f, "IHDR", ihdr, sizeof(ihdr)) == 0 &&
             write_chunk(f, "IDAT", comp, (uint32_t)clen) == 0 &&
             write_chunk(f, "IEND", NULL, 0) == 0;
    if (fclose(f) != 0) ok = 0;
    free(comp);
    if (ok && rename(tmp, path) == 0) return 0;
    remove(tmp);
    return -1;
}

/* ── PNG reader ──────────────────────────────────────────────────────────── */

static int paeth(int a, int b, int c) {
    int p = a + b - c, pa = abs(p - a), pb = abs(p - b), pc = abs(p - c);
    if (pa <= pb && pa <= pc) return a;
    if (pb <= pc) return b;
    return c;
}
static int png_pixels(const char *path, unsigned char **out) {
    FILE *f = fopen(path, "rb");
    if (!f) return -1;
    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return -1; }
    long sz = ftell(f);
    if (sz < 8 || sz > 32 * 1024 * 1024) { fclose(f); return -1; }
    rewind(f);
    unsigned char *buf = malloc((size_t)sz);
    if (!buf || fread(buf, 1, (size_t)sz, f) != (size_t)sz) {
        free(buf); fclose(f); return -1;
    }
    fclose(f);
    static const unsigned char sig[8] = { 0x89, 'P', 'N', 'G', '\r', '\n', 0x1a, '\n' };
    if (memcmp(buf, sig, 8) != 0) { free(buf); return -1; }

    uint32_t w = 0, h = 0;
    unsigned char *idat = NULL;
    size_t idlen = 0, idcap = 0;
    size_t off = 8;
    int ok = 0;
    while (off + 12 <= (size_t)sz) {
        uint32_t clen = get32(buf + off);
        const unsigned char *type = buf + off + 4;
        if ((size_t)clen > (size_t)sz - off - 12) break;
        const unsigned char *data = buf + off + 8;
        uint32_t crc = get32(data + clen);
        uLong c = crc32(0L, Z_NULL, 0);
        c = crc32(c, (const Bytef *)type, 4);
        if (clen) c = crc32(c, data, clen);
        if ((uint32_t)c != crc) break;
        if (memcmp(type, "IHDR", 4) == 0) {
            if (clen != 13) break;
            w = get32(data); h = get32(data + 4);
            if (data[8] != 8 || data[9] != 6 || data[10] != 0 ||
                data[11] != 0 || data[12] != 0) break;
        } else if (memcmp(type, "IDAT", 4) == 0) {
            if (idlen + clen > idcap) {
                size_t nc = idcap ? idcap * 2 : 32768;
                while (nc < idlen + clen) nc *= 2;
                unsigned char *n = realloc(idat, nc);
                if (!n) break;
                idat = n; idcap = nc;
            }
            memcpy(idat + idlen, data, clen);
            idlen += clen;
        } else if (memcmp(type, "IEND", 4) == 0) {
            ok = 1;
            break;
        }
        off += (size_t)clen + 12;
    }
    free(buf);
    if (!ok || w != PNG_W || h != PNG_H || !idat) { free(idat); return -1; }

    size_t stride = PNG_W * PNG_CHANNELS;
    size_t rawlen = PNG_H * (stride + 1);
    unsigned char *raw = malloc(rawlen);
    unsigned char *px = malloc(PNG_PIXELS);
    if (!raw || !px) { free(raw); free(px); free(idat); return -1; }
    uLongf got = (uLongf)rawlen;
    if (uncompress(raw, &got, idat, (uLong)idlen) != Z_OK || got != rawlen) {
        free(raw); free(px); free(idat); return -1;
    }
    free(idat);

    for (int y = 0; y < PNG_H; y++) {
        unsigned char ft = raw[(size_t)y * (stride + 1)];
        const unsigned char *src = raw + (size_t)y * (stride + 1) + 1;
        unsigned char *dst = px + (size_t)y * stride;
        for (size_t x = 0; x < stride; x++) {
            int a = x >= PNG_CHANNELS ? dst[x - PNG_CHANNELS] : 0;
            int b = y > 0 ? px[(size_t)(y - 1) * stride + x] : 0;
            int c = (x >= PNG_CHANNELS && y > 0) ? px[(size_t)(y - 1) * stride + x - PNG_CHANNELS] : 0;
            int v = src[x];
            switch (ft) {
                case 0: break;
                case 1: v += a; break;
                case 2: v += b; break;
                case 3: v += (a + b) / 2; break;
                case 4: v += paeth(a, b, c); break;
                default: free(raw); free(px); return -1;
            }
            dst[x] = (unsigned char)v;
        }
    }
    free(raw);
    *out = px;
    return 0;
}

/* ── package encoding/decoding ───────────────────────────────────────────── */

static int pkg_decode(const char *path, const unsigned char *key, pkg_t *p) {
    unsigned char *px = NULL;
    if (png_pixels(path, &px) != 0) return -1;
    const unsigned char *h = px + PNG_OFFSET;
    if (memcmp(h, STEG_MAGIC, 4) != 0 || h[4] != STEG_VERSION) { free(px); return -1; }
    memcpy(p->stamp, h + 6, STEG_STAMP_LEN);
    p->stamp[STEG_STAMP_LEN] = 0;
    if (!stamp_ok(p->stamp)) { free(px); return -1; }
    p->eop = h[5] & 1;
    p->seq = get32(h + 22);
    p->total = get32(h + 26);
    uint32_t clen = get32(h + 30);
    memcpy(p->sha, h + 34, sizeof(p->sha));
    if (p->total == 0 || p->seq >= p->total || clen < NONCE_BYTES + TAG_BYTES ||
        (size_t)STEG_HDR_LEN + clen > PNG_CAPACITY) {
        free(px); return -1;
    }
    size_t mlen = clen - NONCE_BYTES - TAG_BYTES;
    unsigned char *out = malloc(mlen ? mlen : 1);
    if (!out) { free(px); return -1; }
    const unsigned char *blob = h + STEG_HDR_LEN;
    unsigned long long got = 0;
    if (crypto_aead_xchacha20poly1305_ietf_decrypt(
            out, &got, NULL, blob + NONCE_BYTES, clen - NONCE_BYTES,
            h, STEG_HDR_LEN, blob, key) != 0 || got != mlen) {
        free(out); free(px); return -1;
    }
    unsigned char sha[32];
    crypto_hash_sha256(sha, out, mlen);
    if (sodium_memcmp(sha, p->sha, sizeof(sha)) != 0) {
        free(out); free(px); return -1;
    }
    p->data = out;
    p->len = mlen;
    free(px);
    return 0;
}

static int pkg_write(const char *outdir, const char *addr, const char *stamp,
                     uint32_t seq, uint32_t total, const unsigned char *chunk,
                     size_t len, const unsigned char *key) {
    unsigned char hdr[STEG_HDR_LEN];
    memset(hdr, 0, sizeof(hdr));
    memcpy(hdr, STEG_MAGIC, 4);
    hdr[4] = STEG_VERSION;
    hdr[5] = (seq + 1 == total) ? 1 : 0;   /* explicit EOP on the last package */
    memcpy(hdr + 6, stamp, STEG_STAMP_LEN);
    put32(hdr + 22, seq);
    put32(hdr + 26, total);
    uint32_t clen = (uint32_t)(NONCE_BYTES + len + TAG_BYTES);
    put32(hdr + 30, clen);
    crypto_hash_sha256(hdr + 34, chunk, len);

    unsigned char *px = malloc(PNG_PIXELS);
    if (!px) return -1;
    filler(px, PNG_PIXELS, key, stamp, seq);
    memcpy(px + PNG_OFFSET, hdr, sizeof(hdr));
    unsigned char *blob = px + PNG_OFFSET + STEG_HDR_LEN;
    /* Deterministic nonce, bound to the transfer and the plaintext hash.
       Re-sending a package therefore reproduces it byte-for-byte, while a
       changed chunk gets a different nonce. */
    unsigned char nmsg[96];
    int nm = snprintf((char *)nmsg, sizeof(nmsg), "beaut-steg-nonce|%s|%u|", stamp, seq);
    memcpy(nmsg + nm, hdr + 34, 32);
    crypto_generichash(blob, NONCE_BYTES, nmsg, (size_t)nm + 32, key, KEY_BYTES);
    sodium_memzero(nmsg, sizeof(nmsg));
    unsigned long long outlen = 0;
    if (crypto_aead_xchacha20poly1305_ietf_encrypt(
            blob + NONCE_BYTES, &outlen, chunk, len, hdr, sizeof(hdr),
            NULL, blob, key) != 0) {
        free(px);
        return -1;
    }
    if (NONCE_BYTES + outlen != clen) { free(px); return -1; }

    char date[9];
    memcpy(date, stamp, 8);
    date[8] = 0;
    char path[1200];
    snprintf(path, sizeof(path), "%s/%s-%s-package.%06u.png", outdir, date, addr, seq + 1);
    int rc = write_png(path, px);
    free(px);
    if (rc == 0) printf("package %u/%u %s\n", seq + 1, total, path);
    return rc;
}

static int pack_all(const char *src, const char *outdir, const char *addr,
                    const char *stamp, const int *counters, int ncount,
                    const unsigned char *key) {
    struct stat st;
    if (stat(src, &st) != 0 || !S_ISREG(st.st_mode)) {
        fprintf(stderr, "steg: cannot read %s\n", src);
        return 1;
    }
    long long fsize = (long long)st.st_size;
    long long maxsz = steg_max();
    if (fsize > maxsz) {
        fprintf(stderr, "steg: %s is %lld bytes, over STEGANO_MAX_SIZE=%lld\n",
                src, fsize, maxsz);
        return 1;
    }
    uint32_t total = fsize == 0 ? 1u :
        (uint32_t)((fsize + STEG_CHUNK_MAX - 1) / STEG_CHUNK_MAX);
    FILE *f = fopen(src, "rb");
    if (!f) { fprintf(stderr, "steg: cannot open %s\n", src); return 1; }
    unsigned char *chunk = malloc(STEG_CHUNK_MAX);
    if (!chunk) { fclose(f); return 1; }

    int rc = 0;
    int done = 0;
    for (int i = 0; i < (ncount > 0 ? ncount : (int)total); i++) {
        int counter = ncount > 0 ? counters[i] : i + 1;
        if (counter < 1 || (uint32_t)counter > total) {
            fprintf(stderr, "steg: package %d out of range 1..%u\n", counter, total);
            rc = 1;
            continue;
        }
        uint32_t seq = (uint32_t)counter - 1;
        long long off = (long long)seq * STEG_CHUNK_MAX;
        size_t want = fsize - off < STEG_CHUNK_MAX ? (size_t)(fsize - off) : STEG_CHUNK_MAX;
        if (fsize == 0) want = 0;
        if (fseek(f, (long)off, SEEK_SET) != 0 ||
            (want && fread(chunk, 1, want, f) != want)) {
            fprintf(stderr, "steg: read error at package %d\n", counter);
            rc = 1;
            continue;
        }
        if (pkg_write(outdir, addr, stamp, seq, total, chunk, want, key) != 0) {
            fprintf(stderr, "steg: failed to write package %d\n", counter);
            rc = 1;
        } else {
            done++;
        }
    }
    free(chunk);
    fclose(f);
    printf("stamp=%s total=%u packages=%d bytes=%lld\n", stamp, total, done, fsize);
    return rc;
}

/* ── directory scanning ──────────────────────────────────────────────────── */

typedef struct {
    pkg_t *v;
    int n, cap;
    uint32_t total;
    int total_set;
} coll_t;

static void coll_free(coll_t *c) {
    for (int i = 0; i < c->n; i++) free(c->v[i].data);
    free(c->v);
    memset(c, 0, sizeof(*c));
}
static int scan_dir(const char *dir, const char *stamp, const unsigned char *key, coll_t *c) {
    DIR *d = opendir(dir);
    if (!d) { fprintf(stderr, "steg: cannot open directory %s\n", dir); return -1; }
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        size_t nl = strlen(de->d_name);
        if (nl < 4 || strcmp(de->d_name + nl - 4, ".png") != 0) continue;
        if (!strstr(de->d_name, "-package.")) continue;
        char path[1600];
        snprintf(path, sizeof(path), "%s/%s", dir, de->d_name);
        pkg_t p;
        memset(&p, 0, sizeof(p));
        if (pkg_decode(path, key, &p) != 0) continue;
        if (stamp && strcmp(p.stamp, stamp) != 0) { free(p.data); continue; }
        if (!c->total_set) { c->total = p.total; c->total_set = 1; }
        if (p.total != c->total) { free(p.data); continue; }
        if (c->n == c->cap) {
            int nc = c->cap ? c->cap * 2 : 64;
            pkg_t *nv = realloc(c->v, (size_t)nc * sizeof(pkg_t));
            if (!nv) { free(p.data); closedir(d); return -1; }
            c->v = nv; c->cap = nc;
        }
        c->v[c->n++] = p;
    }
    closedir(d);
    return 0;
}

int steg_pack(const char *src, const char *outdir, const char *addr, const char *stamp) {
    unsigned char key[KEY_BYTES];
    if (steg_key(key) != 0) return 1;
    char st[STEG_STAMP_LEN + 1];
    if (stamp && *stamp) {
        if (!stamp_ok(stamp)) { fputs("steg: stamp must be 16 alphanumeric chars\n", stderr); return 1; }
        snprintf(st, sizeof(st), "%s", stamp);
    } else {
        make_stamp(st);
    }
    char ad[256];
    sanitize_addr(ad, sizeof(ad), addr);
    int rc = pack_all(src, outdir, ad, st, NULL, 0, key);
    sodium_memzero(key, sizeof(key));
    return rc;
}

int steg_resend(const char *src, const char *outdir, const char *stamp,
                int *counters, int n) {
    if (!stamp_ok(stamp)) { fputs("steg: stamp must be 16 alphanumeric chars\n", stderr); return 1; }
    unsigned char key[KEY_BYTES];
    if (steg_key(key) != 0) return 1;
    char ad[256];
    sanitize_addr(ad, sizeof(ad), getenv("BEAUT_STEG_ADDR"));
    int rc = pack_all(src, outdir, ad, stamp, counters, n, key);
    sodium_memzero(key, sizeof(key));
    return rc;
}

int steg_missing(const char *dir, const char *stamp) {
    unsigned char key[KEY_BYTES];
    if (steg_key(key) != 0) return 1;
    coll_t c;
    memset(&c, 0, sizeof(c));
    if (scan_dir(dir, stamp, key, &c) != 0) { coll_free(&c); return 1; }
    if (!c.total_set) {
        printf("missing=all total=0 received=0\n");
        coll_free(&c);
        return 1;
    }
    unsigned char *have = calloc(c.total, 1);
    if (!have) { coll_free(&c); return 1; }
    for (int i = 0; i < c.n; i++) have[c.v[i].seq] = 1;
    int missing = 0;
    printf("missing=");
    for (uint32_t i = 0; i < c.total; i++) {
        if (have[i]) continue;
        printf("%s%u", missing ? "," : "", i + 1);
        missing++;
    }
    if (!missing) printf("none");
    printf(" total=%u received=%d stamp=%s\n", c.total, c.n, c.v[0].stamp);
    free(have);
    coll_free(&c);
    sodium_memzero(key, sizeof(key));
    return 0;
}

int steg_unpack(const char *dir, const char *stamp, const char *out) {
    unsigned char key[KEY_BYTES];
    if (steg_key(key) != 0) return 1;
    coll_t c;
    memset(&c, 0, sizeof(c));
    if (scan_dir(dir, stamp, key, &c) != 0) { coll_free(&c); return 1; }
    if (!c.total_set) {
        fprintf(stderr, "steg: no packages for stamp %s in %s\n", stamp ? stamp : "(any)", dir);
        coll_free(&c);
        return 1;
    }
    pkg_t *slot = calloc(c.total, sizeof(pkg_t));
    unsigned char *have = calloc(c.total, 1);
    if (!slot || !have) { free(slot); free(have); coll_free(&c); return 1; }
    for (int i = 0; i < c.n; i++) {
        uint32_t s = c.v[i].seq;
        if (have[s]) { free(c.v[i].data); continue; }
        slot[s] = c.v[i];
        have[s] = 1;
    }
    free(c.v);
    int missing = 0;
    long long total_bytes = 0;
    for (uint32_t i = 0; i < c.total; i++) {
        if (!have[i]) missing++;
        else total_bytes += (long long)slot[i].len;
    }
    if (missing) {
        printf("missing=");
        int first = 1;
        for (uint32_t i = 0; i < c.total; i++)
            if (!have[i]) { printf("%s%u", first ? "" : ",", i + 1); first = 0; }
        printf(" total=%u stamp=%s\n", c.total, slot[0].stamp);
        for (uint32_t i = 0; i < c.total; i++) if (have[i]) free(slot[i].data);
        free(slot); free(have);
        return 2;
    }
    if (!slot[c.total - 1].eop) {
        fprintf(stderr, "steg: last package has no EOP flag\n");
        for (uint32_t i = 0; i < c.total; i++) free(slot[i].data);
        free(slot); free(have);
        return 1;
    }
    if (total_bytes > steg_max()) {
        fprintf(stderr, "steg: transfer is %lld bytes, over STEGANO_MAX_SIZE=%lld\n",
                total_bytes, steg_max());
        for (uint32_t i = 0; i < c.total; i++) free(slot[i].data);
        free(slot); free(have);
        return 1;
    }
    FILE *f = fopen(out, "wb");
    if (!f) {
        fprintf(stderr, "steg: cannot write %s\n", out);
        for (uint32_t i = 0; i < c.total; i++) free(slot[i].data);
        free(slot); free(have);
        return 1;
    }
    int rc = 0;
    for (uint32_t i = 0; i < c.total; i++) {
        if (slot[i].len && fwrite(slot[i].data, 1, slot[i].len, f) != slot[i].len) {
            rc = 1;
            break;
        }
    }
    fclose(f);
    if (rc == 0) printf("ok %s bytes=%lld packages=%u stamp=%s\n",
                        out, total_bytes, c.total, slot[0].stamp);
    for (uint32_t i = 0; i < c.total; i++) free(slot[i].data);
    free(slot); free(have);
    sodium_memzero(key, sizeof(key));
    return rc;
}

int steg_inspect(const char *path) {
    unsigned char key[KEY_BYTES];
    if (steg_key(key) != 0) return 1;
    pkg_t p;
    memset(&p, 0, sizeof(p));
    if (pkg_decode(path, key, &p) != 0) {
        fprintf(stderr, "steg: not a valid package: %s\n", path);
        sodium_memzero(key, sizeof(key));
        return 1;
    }
    printf("stamp=%s seq=%u total=%u eop=%d bytes=%zu\n",
           p.stamp, p.seq + 1, p.total, p.eop, p.len);
    free(p.data);
    sodium_memzero(key, sizeof(key));
    return 0;
}
